// Meta entrega el mensaje anidado en entry[0].changes[0].value.
// Aquí se aplana a la forma que espera la API de Laravel.
const raw = $input.first().json;
const body = raw.body ?? raw;

const value = body?.entry?.[0]?.changes?.[0]?.value;
const message = value?.messages?.[0];

// Los webhooks de estado (enviado / entregado / leído) no traen 'messages'.
// Sin este corte el bot respondería a sus propios acuses de recibo.
if (!message) {
  return [{ json: { skip: true, motivo: 'webhook de estado, no es un mensaje' } }];
}

const contact = value?.contacts?.[0];

let text = '';
let replyId = null;

switch (message.type) {
  case 'text':
    text = message.text?.body ?? '';
    break;

  case 'interactive':
    // El cliente tocó un botón o eligió una fila de la lista.
    // El id es lo que interpreta la máquina de estados; el título es solo
    // lo que el cliente vio en pantalla.
    if (message.interactive?.type === 'button_reply') {
      replyId = message.interactive.button_reply?.id ?? null;
      text = message.interactive.button_reply?.title ?? '';
    } else if (message.interactive?.type === 'list_reply') {
      replyId = message.interactive.list_reply?.id ?? null;
      text = message.interactive.list_reply?.title ?? '';
    }
    break;

  case 'button':
    // Botón de una plantilla, formato distinto al interactivo.
    text = message.button?.text ?? '';
    replyId = message.button?.payload ?? null;
    break;

  default:
    // Audio, imagen, ubicación, documento... El bot todavía no los interpreta,
    // pero se registran igual para que el asesor los vea en el panel.
    text = '';
}

return [{
  json: {
    skip: false,
    wa_id: message.from,
    profile_name: contact?.profile?.name ?? null,
    wa_message_id: message.id,
    type: message.type,
    text,
    reply_id: replyId,
  },
}];

// Arma el cuerpo de la petición a la API de Claude.
const laravel = $input.first().json;
const ai = laravel.ai ?? {};

// El historial ya viene ordenado y termina con el mensaje actual del cliente.
let history = (ai.history ?? []).filter(
  (m) => typeof m.content === 'string' && m.content.trim() !== ''
);

// La conversación debe empezar por el usuario: si la ventana de 10 mensajes
// cortó justo en una respuesta del bot, se descartan esas primeras.
while (history.length > 0 && history[0].role !== 'user') {
  history.shift();
}

// Y debe terminar por el usuario, que es a quien Claude tiene que contestar.
if (history.length === 0 || history[history.length - 1].role !== 'user') {
  history.push({ role: 'user', content: ai.message ?? '' });
}

return [{
  json: {
    conversation_id: laravel.conversation_id,
    requestBody: {
      model: 'claude-opus-5',
      max_tokens: 2048,
      // Esfuerzo bajo: son respuestas cortas de chat, no razonamiento profundo.
      // Baja la latencia y el costo sin perder calidad en este caso de uso.
      output_config: { effort: 'low' },
      system: ai.system ?? '',
      messages: history,
    },
  },
}];

// Extrae el texto de la respuesta de Claude.
const res = $input.first().json;

// Claude Opus 5 razona por defecto, así que el primer bloque del contenido
// suele ser de tipo 'thinking' con texto vacío. Hay que filtrar por el bloque
// de tipo 'text': leer content[0] devolvería una cadena vacía.
const text = (res.content ?? [])
  .filter((b) => b.type === 'text')
  .map((b) => b.text)
  .join('\n')
  .trim();

// Los clasificadores de seguridad pueden declinar una consulta. No llega como
// error HTTP: llega un 200 con stop_reason 'refusal'. Ante eso, mejor pasar a
// un humano que dejar al cliente sin respuesta.
if (res.stop_reason === 'refusal' || text === '') {
  return [{
    json: {
      reply: {
        kind: 'text',
        body: 'Prefiero que esta consulta la vea un asesor de Mavkora 🙌 Escribe *asesor* y te conecto con una persona del equipo, o *menu* para volver al inicio.',
      },
      generated_by: 'flow',
    },
  }];
}

return [{ json: { reply: { kind: 'text', body: text }, generated_by: 'ai' } }];

// Traduce la respuesta genérica de Laravel al formato de la Cloud API.
const entrada = $input.first().json;
const normalizado = $('Normalizar mensaje').first().json;
const laravel = $('Laravel: procesar mensaje').first().json;

// Si venimos de la rama de IA, el texto llega en la entrada;
// si no, se usa la respuesta que ya calculó Laravel.
const reply = entrada.reply ?? laravel.reply;
const generadoPor = entrada.generated_by ?? 'flow';

const to = normalizado.wa_id;
const base = { messaging_product: 'whatsapp', recipient_type: 'individual', to };

// 'none' significa que el bot debe callarse: un asesor tomó la conversación,
// o el mensaje era un reintento de Meta que ya se había respondido.
if (!reply || reply.kind === 'none') {
  return [{ json: { send: false, motivo: 'sin respuesta que enviar' } }];
}

let payload;

if (reply.kind === 'text') {
  payload = { ...base, type: 'text', text: { preview_url: false, body: reply.body } };
} else if (reply.kind === 'buttons') {
  payload = {
    ...base,
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: reply.body },
      ...(reply.footer ? { footer: { text: reply.footer } } : {}),
      action: {
        buttons: (reply.buttons ?? []).map((b) => ({
          type: 'reply',
          reply: { id: b.id, title: b.title },
        })),
      },
    },
  };
} else if (reply.kind === 'list') {
  payload = {
    ...base,
    type: 'interactive',
    interactive: {
      type: 'list',
      body: { text: reply.body },
      ...(reply.footer ? { footer: { text: reply.footer } } : {}),
      action: {
        button: reply.button,
        // Meta rechaza un 'title' nulo en las secciones, así que se omite.
        sections: (reply.sections ?? []).map((s) => ({
          ...(s.title ? { title: s.title } : {}),
          rows: s.rows,
        })),
      },
    },
  };
} else {
  return [{ json: { send: false, motivo: 'tipo de respuesta desconocido: ' + reply.kind } }];
}

return [{
  json: {
    send: true,
    payload,
    conversation_id: laravel.conversation_id,
    generated_by: generadoPor,
    body_texto: reply.body ?? '',
    tipo: reply.kind,
  },
}];

